const { data } = useQuery({
  queryKey: ['users'],
  queryFn: fetchUsers,

  // Caching
  staleTime: 1000 * 60 * 5,    // Data fresh for 5 min
  gcTime: 1000 * 60 * 30,      // Cache for 30 min

  // Refetching
  refetchOnWindowFocus: true,  // Refetch on focus
  refetchOnMount: true,        // Refetch on mount
  refetchInterval: 5000,       // Poll every 5 sec

  // Behavior
  enabled: !!userId,           // Conditional query
  retry: 3,                    // Retry 3 times
  retryDelay: 1000,            // Wait between retries

  // Data transformation
  select: (data) => data.users // Transform response
});
